import React, { useState, useEffect } from "react";
import { useNavigate } from "react-router-dom";
import axios from "axios";
import "./manageUserAccounts.css";
import AdminSidebar from "../components/AdminSideBar";
import Navbar from "../components/navbar";
import Footer from "../components/footer";

function ManageUserAccounts() {
  const [name, setName] = useState("");
  const [email, setEmail] = useState("");
  const [role, setRole] = useState("");
  const [registrationNumber, setRegistrationNumber] = useState("");
  const [password, setPassword] = useState("");

  const [students, setStudents] = useState([]);
  const [supervisors, setSupervisors] = useState([]);
  const [evaluators, setEvaluators] = useState([]);

  const [viewStudents, setViewStudents] = useState(false);
  const [viewSupervisors, setViewSupervisors] = useState(false);
  const [viewEvaluators, setViewEvaluators] = useState(false);

  const [editingIndex, setEditingIndex] = useState(null);
  const [editingType, setEditingType] = useState("");

  const navigate = useNavigate();

  useEffect(() => {
    const fetchData = async () => {
      try {
        const studentsResponse = await axios.get("/api/student");
        const supervisorsResponse = await axios.get("/api/admin");
        const evaluatorsResponse = await axios.get("/api/evaluator");

        // Debugging: Check if we are receiving the correct data
        console.log("Students:", studentsResponse.data);
        console.log("Supervisors:", supervisorsResponse.data);
        console.log("Evaluators:", evaluatorsResponse.data);

        setStudents(studentsResponse.data);
        setSupervisors(supervisorsResponse.data);
        setEvaluators(evaluatorsResponse.data);

        // Set the default views based on data availability
        setViewStudents(studentsResponse.data.length > 0);
        setViewSupervisors(supervisorsResponse.data.length > 0);
        setViewEvaluators(evaluatorsResponse.data.length > 0);
      } catch (err) {
        console.error("Error fetching data", err);
      }
    };

    fetchData();
  }, []);

  const handleSubmit = async (e) => {
    e.preventDefault();
    const newUser = { name, email, role, registrationNumber, password };

    try {
      if (editingIndex !== null) {
        if (editingType === "student") {
          await axios.patch(`/api/student/${students[editingIndex]._id}`, newUser);
          const updated = [...students];
          updated[editingIndex] = newUser;
          setStudents(updated);
        } else if (editingType === "supervisor") {
          await axios.patch(`/api/admin/${supervisors[editingIndex]._id}`, newUser);
          const updated = [...supervisors];
          updated[editingIndex] = newUser;
          setSupervisors(updated);
        } else if (editingType === "evaluator") {
          await axios.patch(`/api/evaluator/${evaluators[editingIndex]._id}`, newUser);
          const updated = [...evaluators];
          updated[editingIndex] = newUser;
          setEvaluators(updated);
        }
        setEditingIndex(null);
        setEditingType("");
      } else {
        if (role === "Student") {
          await axios.post("/api/student", newUser);
          setStudents([...students, newUser]);
          setViewStudents(true);
        } else if (role === "Supervisor") {
          await axios.post("/api/admin", newUser);
          setSupervisors([...supervisors, newUser]);
          setViewSupervisors(true);
        } else if (role === "Evaluator") {
          await axios.post("/api/evaluator", newUser);
          setEvaluators([...evaluators, newUser]);
          setViewEvaluators(true);
        }
      }
    } catch (error) {
      console.error("Error creating/updating user", error);
    }

    // Clear form fields
    setName("");
    setEmail("");
    setRole("");
    setRegistrationNumber("");
    setPassword("");
  };

  const handleEdit = (index, type) => {
    setEditingIndex(index);
    setEditingType(type);
    const user =
      type === "student"
        ? students[index]
        : type === "supervisor"
        ? supervisors[index]
        : evaluators[index];
    setName(user.name);
    setEmail(user.email);
    setRole(user.role);
    setRegistrationNumber(user.registrationNumber || "");
    setPassword(user.password || "");
  };

  const handleDelete = async (userId, type, id) => {
    try {
      if (type === "student") {
        await axios.delete(`/api/student/${id}`);
        setStudents(students.filter((student) => student._id !== id));
      } else if (type === "supervisor") {
        await axios.delete(`/api/admin/${id}`);
        setSupervisors(supervisors.filter((supervisor) => supervisor._id !== id));
      } else if (type === "evaluator") {
        await axios.delete(`/api/evaluator/${id}`);
        setEvaluators(evaluators.filter((evaluator) => evaluator._id !== id));
      }
    } catch (err) {
      console.error("Error deleting user", err);
    }
  };

  const handleResetPassword = async (userId, type) => {
    const newPassword = prompt("Enter new password:");
    if (newPassword) {
      try {
        if (type === "student") {
          await axios.patch(`/api/student/${userId}`, { password: newPassword });
          alert("Password reset successfully for student.");
        } else if (type === "supervisor") {
          await axios.patch(`/api/admin/${userId}`, { password: newPassword });
          alert("Password reset successfully for supervisor.");
        } else if (type === "evaluator") {
          await axios.patch(`/api/evaluator/${userId}`, { password: newPassword });
          alert("Password reset successfully for evaluator.");
        }
      } catch (err) {
        console.error("Error resetting password", err);
      }
    }
  };

  return (
    <div className="manage-user-accounts">
      <Navbar />
      <div className="content-wrapper">
        <AdminSidebar />
        <div className="main-content">
          <h1>Manage User Accounts</h1>
          <p>Add or edit accounts for students, supervisors, and evaluators</p>

          <div className="user-form-container">
            <h2>{editingIndex !== null ? "Edit User" : "Add / Edit User"}</h2>
            <form onSubmit={handleSubmit} className="user-form">
              <label htmlFor="name">Name</label>
              <input
                type="text"
                id="name"
                value={name}
                onChange={(e) => setName(e.target.value)}
                required
              />

              <label htmlFor="email">Email</label>
              <input
                type="email"
                id="email"
                value={email}
                onChange={(e) => setEmail(e.target.value)}
                required
              />

              <label htmlFor="password">Password</label>
              <input
                type="password"
                id="password"
                value={password}
                onChange={(e) => setPassword(e.target.value)}
                required
              />

              <label htmlFor="role">Role</label>
              <select
                id="role"
                value={role}
                onChange={(e) => setRole(e.target.value)}
                required
              >
                <option value="">Select Role</option>
                <option value="Student">Student</option>
                <option value="Supervisor">Supervisor</option>
                <option value="Evaluator">Evaluator</option>
              </select>

              {role === "Student" && (
                <>
                  <label htmlFor="registrationNumber">Registration Number</label>
                  <input
                    type="text"
                    id="registrationNumber"
                    value={registrationNumber}
                    onChange={(e) => setRegistrationNumber(e.target.value)}
                    required
                  />
                </>
              )}

              {role === "Evaluator" && (
                <>
                  <label htmlFor="registrationNumber">Registration Number</label>
                  <input
                    type="text"
                    id="registrationNumber"
                    disabled
                    placeholder="Not applicable"
                  />
                </>
              )}

              <button type="submit" className="submit-btn">
                {editingIndex !== null ? "Update" : "Submit"}
              </button>
            </form>
          </div>

          {/* Render student table */}
          {viewStudents && students.length > 0 && (
            <div className="student-table">
              <h2>Student List</h2>
              <table>
                <thead>
                  <tr>
                    <th>Name</th>
                    <th>Email</th>
                    <th>Role</th>
                    <th>Registration Number</th>
                    <th>Actions</th>
                  </tr>
                </thead>
                <tbody>
                  {students.map((student, index) => (
                    <tr key={index}>
                      <td>{student.studentName}</td>
                      <td>{student.email}</td>
                      <td>{student.role}</td>
                      <td>{student.regNo}</td>
                      <td>
                        <button onClick={() => handleEdit(index, "student")}>Edit</button>
                        <button onClick={() => handleResetPassword(student.userId, "student")}>
                          Reset Password
                        </button>
                        <button onClick={() => handleDelete(student.userId, "student", student._id)}>
                          Delete
                        </button>
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          )}

          {/* Render supervisor table */}
          {viewSupervisors && supervisors.length > 0 && (
            <div className="supervisor-table">
              <h2>Supervisor List</h2>
              <table>
                <thead>
                  <tr>
                    <th>Name</th>
                    <th>Email</th>
                    <th>Role</th>
                    <th>Actions</th>
                  </tr>
                </thead>
                <tbody>
                  {supervisors.map((supervisor, index) => (
                    <tr key={index}>
                      <td>{supervisor.name}</td>
                      <td>{supervisor.email}</td>
                      <td>{supervisor.role}</td>
                      <td>
                        <button onClick={() => handleEdit(index, "supervisor")}>Edit</button>
                        <button onClick={() => handleResetPassword(supervisor.userId, "supervisor")}>
                          Reset Password
                        </button>
                        <button onClick={() => handleDelete(supervisor.userId, "admin", supervisor._id)}>
                          Delete
                        </button>
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          )}

          {/* Render evaluator table */}
          {viewEvaluators && evaluators.length > 0 && (
            <div className="evaluator-table">
              <h2>Evaluator List</h2>
              <table>
                <thead>
                  <tr>
                    <th>Name</th>
                    <th>Email</th>
                    <th>Role</th>
                    <th>Actions</th>
                  </tr>
                </thead>
                <tbody>
                  {evaluators.map((evaluator, index) => (
                    <tr key={index}>
                      <td>{evaluator.name}</td>
                      <td>{evaluator.email}</td>
                      <td>{evaluator.role}</td>
                      <td>
                        <button onClick={() => handleEdit(index, "evaluator")}>Edit</button>
                        <button onClick={() => handleResetPassword(evaluator.userId, "evaluator")}>
                          Reset Password
                        </button>
                        <button onClick={() => handleDelete(evaluator.userId, "evaluator", evaluator._id)}>
                          Delete
                        </button>
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          )}
        </div>
      </div>
      <Footer />
    </div>
  );
}

export default ManageUserAccounts;
